struct Element {
    let id: String
    var count: Int
    mutating func tap() { count += 1 }
}
var btn = Element(id: "submit", count: 1)
btn.tap()
print(btn.count)

struct Config {
    let args: [String]
    var isTestMode: Bool { args.contains("--test") }
}
let c = Config(args: ["--test", "--mock"])
print(c.isTestMode ? "Testing" : "Live")

struct Page {
    var field = ""
    mutating func enter(text: String) { field = text }
}
var p = Page()
p.enter(text: "Alex")
print("User: \(p.field)")

struct ViewItem {
    let label: String
    let identifier: String
}
let item = ViewItem(label: "Iniciar sesión", identifier: "login_button")
print(item.identifier)

struct Waiter {
    func check(exists: Bool) -> String {
        return exists ? "Found" : "Timeout"
    }
}
let w = Waiter()
print(w.check(exists: true))

struct Screen {
    var steps: [String] = []
    mutating func record(_ step: String) { steps.append(step) }
}
var s = Screen()
s.record("tap_login")
s.record("tap_submit")
print(s.steps.count)

struct LaunchFlags {
    var flags: Set<String> = []
    mutating func add(_ f: String) { flags.insert(f) }
}
var l = LaunchFlags()
l.add("--mock-api")
